"""The book file: one SQLite database with numbered schema versions."""

import datetime
import json
import os
import re
import sqlite3
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import TYPES, Chart, ChartError, path_key
from tallybook.currency import RateTable, is_currency
from tallybook.dates import format_date, parse_date
from tallybook.errors import (ConflictError, NotFoundError, TallybookError, ValidationError, is_int)
from tallybook.ledger import Ledger, LedgerError
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money

__all__ = ["Store", "LATEST_VERSION", "BulkAdd", "ImportOutcome"]

LATEST_VERSION = 4
SQLITE_HEADER = b"SQLite format 3\x00"
PROFILE_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


@dataclass
class BulkAdd:
    added: List[Transaction] = field(default_factory=list)
    skipped: List[int] = field(default_factory=list)


@dataclass
class ImportOutcome:
    added: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: list = field(default_factory=list)


# ---------------------------------------------------------------------------- migrations
def _migrate_1(conn):
    conn.execute("CREATE TABLE accounts (path TEXT PRIMARY KEY, type TEXT NOT NULL, currency TEXT, opened TEXT, "
                 "note TEXT NOT NULL DEFAULT '')")
    conn.execute("CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, "
                 "payee TEXT NOT NULL, narration TEXT NOT NULL DEFAULT '', cleared INTEGER NOT NULL DEFAULT 1)")
    conn.execute("CREATE TABLE postings (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                 "tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, "
                 "seq INTEGER NOT NULL, account TEXT NOT NULL REFERENCES accounts(path), "
                 "minor INTEGER NOT NULL, currency TEXT NOT NULL)")
    conn.execute("CREATE INDEX transactions_date_id ON transactions(date, id)")
    conn.execute("CREATE INDEX postings_tx_seq ON postings(tx_id, seq)")


def _migrate_2(conn):
    bad = conn.execute("SELECT COUNT(*) FROM transactions WHERE cleared IS NULL OR cleared NOT IN (0, 1)").fetchone()
    if bad[0]:
        raise ValueError("%d transactions have a cleared value that is not 0 or 1" % bad[0])
    conn.execute("CREATE TABLE tags (tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, "
                 "tag TEXT NOT NULL, PRIMARY KEY (tx_id, tag))")
    conn.execute("ALTER TABLE transactions ADD COLUMN flag TEXT NOT NULL DEFAULT '*'")
    conn.execute("ALTER TABLE postings ADD COLUMN note TEXT NOT NULL DEFAULT ''")
    conn.execute("UPDATE transactions SET flag = CASE cleared WHEN 0 THEN '!' ELSE '*' END")


_THREE_LETTERS = re.compile(r"[A-Z]{3}")


def _clean_currency(value):
    if value is None:
        return None
    if not isinstance(value, str):
        value = str(value)
    return value.strip(" \t\r\n\f\v").upper()


def _migrate_3(conn):
    conn.execute("CREATE TABLE rates (src TEXT NOT NULL, dst TEXT NOT NULL, on_date TEXT NOT NULL, "
                 "rate_text TEXT NOT NULL, PRIMARY KEY (src, dst, on_date))")
    conn.execute("ALTER TABLE accounts ADD COLUMN closed TEXT")
    for path, cur in conn.execute("SELECT path, currency FROM accounts").fetchall():
        if cur is None:
            continue
        cleaned = _clean_currency(cur)
        if cleaned == "":
            cleaned = None
        elif not _THREE_LETTERS.fullmatch(cleaned):
            raise ValueError("account %s has an invalid currency %r" % (path, cur))
        if cleaned != cur:
            conn.execute("UPDATE accounts SET currency = ? WHERE path = ?", (cleaned, path))
    for pid, cur in conn.execute("SELECT id, currency FROM postings").fetchall():
        cleaned = _clean_currency(cur)
        if cleaned is None or not _THREE_LETTERS.fullmatch(cleaned):
            raise ValueError("posting %s has an invalid currency %r" % (pid, cur))
        if cleaned != cur:
            conn.execute("UPDATE postings SET currency = ? WHERE id = ?", (cleaned, pid))


def _migrate_4(conn):
    conn.execute("CREATE TABLE budgets (pattern TEXT NOT NULL, period_kind TEXT NOT NULL, minor INTEGER NOT NULL, "
                 "currency TEXT NOT NULL, start_date TEXT NOT NULL, PRIMARY KEY (pattern, period_kind))")
    conn.execute("CREATE TABLE recurring (name TEXT PRIMARY KEY, schedule TEXT NOT NULL, template TEXT NOT NULL, "
                 "start_date TEXT NOT NULL, end_date TEXT, max_count INTEGER, materialized_through TEXT)")
    conn.execute("CREATE TABLE rules (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL)")
    conn.execute("CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
    conn.execute("CREATE TABLE import_keys (key TEXT PRIMARY KEY, "
                 "tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE)")


MIGRATIONS = {1: _migrate_1, 2: _migrate_2, 3: _migrate_3, 4: _migrate_4}


# ---------------------------------------------------------------------------- helpers
def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _d(text):
    return parse_date(text) if text is not None else None


def _ds(value):
    return format_date(value) if value is not None else None


def _template_to_json(tx):
    return json.dumps({
        "date": _ds(tx.date) if _is_date(tx.date) else None,
        "payee": tx.payee,
        "narration": tx.narration,
        "flag": tx.flag,
        "tags": list(tx.tags),
        "tags_list": isinstance(tx.tags, list),
        "id": tx.id,
        "postings": [{"account": p.account,
                      "amount": None if p.amount is None else [p.amount.minor, p.amount.currency],
                      "note": p.note} for p in tx.postings],
    }, sort_keys=True, ensure_ascii=False)


def _template_from_json(text):
    data = json.loads(text)
    postings = [Posting(p["account"], None if p["amount"] is None else Money(p["amount"][0], p["amount"][1]),
                        p.get("note", "")) for p in data["postings"]]
    tags = list(data["tags"]) if data.get("tags_list") else tuple(data["tags"])
    return Transaction(_d(data["date"]), data["payee"], data["narration"], postings, tags, data["flag"], data["id"])


class Store:
    """A tallybook book file."""

    def __init__(self, path, conn):
        self.path = path
        self._conn = conn
        self._closed = False

    # ------------------------------------------------------------------ opening
    @classmethod
    def open(cls, path, create=False):
        given = path
        fs = os.fspath(path)
        if os.path.isdir(fs):
            raise ConflictError("%s is a directory, not a tallybook book" % fs)
        exists = os.path.exists(fs)
        if not exists:
            if not create:
                raise NotFoundError("no such database: %s" % fs)
            parent = os.path.dirname(os.path.abspath(fs))
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % (os.path.dirname(fs) or parent))
        else:
            try:
                with open(fs, "rb") as fh:
                    head = fh.read(16)
            except OSError as e:
                raise ConflictError("cannot read %s: %s" % (fs, e.strerror or e)) from None
            if head and head != SQLITE_HEADER:
                raise ConflictError("%s is not a tallybook book" % fs)
        try:
            conn = sqlite3.connect(fs, timeout=5.0, isolation_level=None, check_same_thread=False)
        except sqlite3.Error as e:
            raise ConflictError("cannot open %s: %s" % (fs, e)) from None
        store = cls(given if isinstance(given, str) else fs, conn)
        try:
            conn.execute("PRAGMA foreign_keys = ON")
            version = store._read_version()
            if version == 0:
                tables = conn.execute("SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' "
                                      "AND name NOT LIKE 'sqlite_%'").fetchone()[0]
                if tables:
                    raise ConflictError("%s is not a tallybook book" % fs)
            if version > LATEST_VERSION:
                raise ConflictError("%s is at version %d, newer than this tallybook (version %d)"
                                    % (fs, version, LATEST_VERSION))
            if create and version == 0:
                store.migrate()
        except sqlite3.DatabaseError as e:
            conn.close()
            raise ConflictError("%s is not a tallybook book: %s" % (fs, e)) from None
        except BaseException:
            conn.close()
            raise
        return store

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        if not self._closed:
            self._closed = True
            try:
                self._conn.close()
            except sqlite3.Error:
                pass

    def _check_open(self):
        if self._closed:
            raise ConflictError("the book is closed")

    def _read_version(self):
        try:
            return self._conn.execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.OperationalError as e:
            raise ConflictError("database is busy: %s" % e) from None

    @property
    def version(self):
        self._check_open()
        return self._read_version()

    def _require(self):
        self._check_open()
        v = self._read_version()
        if v != LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)

    def migrate(self):
        self._check_open()
        applied = []
        current = self._read_version()
        if current > LATEST_VERSION:
            raise ConflictError("database is at version %d, newer than this tallybook" % current)
        for v in range(current + 1, LATEST_VERSION + 1):
            try:
                self._conn.execute("BEGIN IMMEDIATE")
            except sqlite3.OperationalError as e:
                raise ConflictError("database is busy: %s" % e) from None
            try:
                MIGRATIONS[v](self._conn)
                self._conn.execute("PRAGMA user_version = %d" % v)
                self._conn.execute("COMMIT")
            except Exception as e:
                try:
                    self._conn.execute("ROLLBACK")
                except sqlite3.Error:
                    pass
                raise ConflictError("migration to version %d failed: %s" % (v, e)) from None
            applied.append(v)
        return applied

    # ------------------------------------------------------------ transactions
    def _q(self, sql, args=()):
        try:
            return self._conn.execute(sql, args).fetchall()
        except sqlite3.OperationalError as e:
            if "locked" in str(e) or "busy" in str(e):
                raise ConflictError("database is busy: %s" % e) from None
            raise

    def _write(self, fn):
        """Run fn() inside one write transaction; all or nothing."""
        try:
            self._conn.execute("BEGIN IMMEDIATE")
        except sqlite3.OperationalError as e:
            raise ConflictError("database is busy: %s" % e) from None
        try:
            result = fn()
            self._conn.execute("COMMIT")
            return result
        except sqlite3.IntegrityError as e:
            self._rollback()
            raise ConflictError("database constraint failed: %s" % e) from None
        except sqlite3.OperationalError as e:
            self._rollback()
            if "locked" in str(e) or "busy" in str(e):
                raise ConflictError("database is busy: %s" % e) from None
            raise
        except BaseException:
            self._rollback()
            raise

    def _rollback(self):
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass

    # ---------------------------------------------------------------- accounts
    def _account_rows(self):
        return self._q("SELECT path, type, currency, opened, closed, note FROM accounts")

    @staticmethod
    def _row_account(row):
        path, typ, cur, opened, closed, note = row
        from tallybook.accounts import ROOT_TYPES
        t = ROOT_TYPES.get(path.split(":", 1)[0], typ)
        return Account(path, t, cur, _d(opened), _d(closed), note or "")

    def _build_chart(self):
        chart = Chart()
        rows = sorted(self._account_rows(), key=lambda r: path_key(r[0]))
        for row in rows:
            acc = self._row_account(row)
            try:
                stored = chart.add(acc.path, opened=acc.opened, note=acc.note)
            except ChartError:
                continue
            stored.currency = acc.currency
            stored.closed = acc.closed
        return chart

    def chart(self):
        self._require()
        return self._build_chart()

    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        self._require()
        chart = self._build_chart()
        acc = chart.add(path, type=type, currency=currency, opened=opened, note=note)

        def go():
            self._conn.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) "
                               "VALUES (?, ?, ?, ?, ?, NULL)", (acc.path, acc.type, acc.currency,
                                                                 _ds(acc.opened), acc.note))
        self._write(go)
        return self.get_account(path)

    def get_account(self, path):
        self._require()
        rows = self._q("SELECT path, type, currency, opened, closed, note FROM accounts WHERE path = ?",
                       (path,)) if isinstance(path, str) else []
        if not rows:
            raise NotFoundError("no such account %s" % (path if isinstance(path, str) else repr(path)))
        return self._row_account(rows[0])

    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        self._require()
        if type is not None and type not in TYPES:
            raise ValidationError("invalid account type %r: expected one of %s" % (type, ", ".join(TYPES)))
        out = []
        for row in self._account_rows():
            acc = self._row_account(row)
            if type is not None and acc.type != type:
                continue
            if under is not None and not (acc.path == under or acc.path.startswith(str(under) + ":")):
                continue
            if currency is not None and acc.currency != currency:
                continue
            if not include_closed and acc.closed is not None:
                continue
            out.append(acc)
        out.sort(key=lambda a: path_key(a.path))
        return out

    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        return len(self.accounts(type=type, under=under, currency=currency, include_closed=include_closed))

    def close_account(self, path, on):
        self._require()
        self.get_account(path)
        chart = self._build_chart()
        chart.close(path, on)
        last = self._q("SELECT MAX(t.date) FROM postings p JOIN transactions t ON t.id = p.tx_id "
                       "WHERE p.account = ?", (path,))[0][0]
        if last is not None and last > format_date(on):
            raise ConflictError("cannot close %s on %s: it has a posting on %s" % (path, format_date(on), last))

        def go():
            self._conn.execute("UPDATE accounts SET closed = ? WHERE path = ?", (format_date(on), path))
        self._write(go)
        return self.get_account(path)

    def set_account_note(self, path, note):
        self._require()
        self.get_account(path)
        if not isinstance(note, str):
            raise ValidationError("invalid note %r" % (note,))

        def go():
            self._conn.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
        self._write(go)
        return self.get_account(path)

    def delete_account(self, path):
        self._require()
        self.get_account(path)
        used = self._q("SELECT COUNT(*) FROM postings WHERE account = ?", (path,))[0][0]
        if used:
            raise ConflictError("account %s has postings and cannot be deleted" % path)

        def go():
            self._conn.execute("DELETE FROM accounts WHERE path = ?", (path,))
        self._write(go)

    # ------------------------------------------------------------ transactions
    def _load_transactions(self, ids=None):
        if ids is None:
            txrows = self._q("SELECT id, date, payee, narration, flag FROM transactions ORDER BY date, id")
            prows = self._q("SELECT tx_id, account, minor, currency, note FROM postings ORDER BY tx_id, seq, id")
            trows = self._q("SELECT tx_id, tag FROM tags")
        else:
            marks = ",".join("?" * len(ids))
            txrows = self._q("SELECT id, date, payee, narration, flag FROM transactions WHERE id IN (%s) "
                             "ORDER BY date, id" % marks, tuple(ids))
            prows = self._q("SELECT tx_id, account, minor, currency, note FROM postings WHERE tx_id IN (%s) "
                            "ORDER BY tx_id, seq, id" % marks, tuple(ids))
            trows = self._q("SELECT tx_id, tag FROM tags WHERE tx_id IN (%s)" % marks, tuple(ids))
        postings = {}

    postings = {}
    for tx_id, account, minor, cur, note in prows:
        postings.setdefault(tx_id, []).append(Posting(account, Money(minor, cur), note or ""))
    tags = {}
    for tx_id, tag in trows:
        tags.setdefault(tx_id, set()).add(tag)
    out = []
    for tid, date, payee, narration, flag in txrows:
        out.append(Transaction(parse_date(date), payee, narration or "", postings.get(tid, []),
                               tuple(sorted(tags.get(tid, ()))), flag, tid))
    return out

def _build_rates(self):
    table = RateTable()
    for src, dst, on, text in self._q("SELECT src, dst, on_date, rate_text FROM rates"):
        try:
            table.set(src, dst, text, parse_date(on))
        except TallybookError:
            continue
    return table

def _build_ledger(self):
    ledger = Ledger(self._build_chart(), self._build_rates())
    for tx in self._load_transactions():
        ledger._load(tx)
    return ledger

def ledger(self):
    self._require()
    return self._build_ledger()

def _next_id(self):
    top = self._q("SELECT MAX(id) FROM transactions")[0][0] or 0
    try:
        seq = self._q("SELECT seq FROM sqlite_sequence WHERE name = 'transactions'")
    except sqlite3.OperationalError:
        seq = []
    if seq and seq[0][0] is not None:
        top = max(top, seq[0][0])
    return top + 1

def _validator(self):
    return Ledger(self._build_chart(), self._build_rates())

def _ensure_account_rows(self, chart, tx):
    stored = {r[0] for r in self._q("SELECT path FROM accounts")}
    for p in tx.postings:
        if p.account not in stored:
            acc = chart.get(p.account)
            self._conn.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) "
                               "VALUES (?, ?, ?, ?, ?, ?)", (acc.path, acc.type, acc.currency,
                                                             _ds(acc.opened), acc.note, _ds(acc.closed)))
            stored.add(p.account)

def _insert_tx(self, tx, chart):
    self._ensure_account_rows(chart, tx)
    self._conn.execute("INSERT INTO transactions (id, date, payee, narration, cleared, flag) "
                       "VALUES (?, ?, ?, ?, ?, ?)",
                       (tx.id, format_date(tx.date), tx.payee, tx.narration, 1 if tx.flag == "*" else 0,
                        tx.flag))
    for seq, p in enumerate(tx.postings):
        self._conn.execute("INSERT INTO postings (tx_id, seq, account, minor, currency, note) "
                           "VALUES (?, ?, ?, ?, ?, ?)",
                           (tx.id, seq, p.account, p.amount.minor, p.amount.currency, p.note))
    for tag in tx.tags:
        self._conn.execute("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", (tx.id, tag))

@staticmethod
def _without_id(tx):
    if not isinstance(tx, Transaction):
        raise LedgerError("not a transaction: %r" % (tx,))
    return Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None)

def add_transaction(self, tx):
    self._require()
    ledger = self._validator()
    stored = ledger.add(self._without_id(tx))

    def go():
        stored.id = self._next_id()
        self._insert_tx(stored, ledger.chart)
        return stored
    return self._write(go)

def add_transactions(self, txs, keys=None):
    self._require()
    txs = list(txs)
    if keys is not None:
        keys = list(keys)
        if len(keys) != len(txs) or not all(isinstance(k, str) for k in keys):
            raise ValidationError("keys must be one text per transaction")
    existing_keys = {r[0] for r in self._q("SELECT key FROM import_keys")} if keys is not None else set()
    ledger = self._validator()
    prepared = []
    skipped = []
    seen = set()
    for i, tx in enumerate(txs):
        if keys is not None:
            k = keys[i]
            if k in existing_keys or k in seen:
                skipped.append(i)
                continue
            seen.add(k)
        try:
            stored = ledger.add(self._without_id(tx))
        except TallybookError as e:
            e.detail = dict(e.detail or {})
            e.detail["index"] = i
            raise
        prepared.append((i, stored))

    def go():
        nid = self._next_id()
        out = []
        for i, stored in prepared:
            stored.id = nid
            nid += 1
            self._insert_tx(stored, ledger.chart)
            if keys is not None:
                self._conn.execute("INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (keys[i], stored.id))
            out.append(stored)
        return out
    added = self._write(go) if prepared else []
    return BulkAdd(added=added, skipped=skipped)

def _parse_query(self, query):
    from tallybook.query import Query, parse_query
    if query is None:
        return None
    if isinstance(query, Query):
        return None if query.is_empty else query
    if not isinstance(query, str):
        raise ValidationError("invalid query %r" % (query,))
    if not query.strip():
        return None
    return parse_query(query, chart=self._build_chart())

def transactions(self, query=None, limit=None, offset=0):
    self._require()
    if limit is not None and (not is_int(limit) or limit < 0):
        raise ValidationError("invalid limit %r: expected a whole number of at least 0" % (limit,))
    if not is_int(offset) or offset < 0:
        raise ValidationError("invalid offset %r: expected a whole number of at least 0" % (offset,))
    q = self._parse_query(query)
    txs = self._load_transactions()
    if q is not None:
        txs = [t for t in txs if q.matches(t)]
    txs = txs[offset:]
    if limit is not None:
        txs = txs[:limit]
    return txs

def count_transactions(self, query=None):
    self._require()
    q = self._parse_query(query)
    if q is None:
        return self._q("SELECT COUNT(*) FROM transactions")[0][0]
    return sum(1 for t in self._load_transactions() if q.matches(t))

def has_import_key(self, key):
    self._require()
    return bool(self._q("SELECT 1 FROM import_keys WHERE key = ?", (key,)))

def get_transaction(self, id):
    self._require()
    if not is_int(id):
        raise NotFoundError("no transaction %r" % (id,))
    txs = self._load_transactions([id])
    if not txs:
        raise NotFoundError("no transaction %r" % (id,))
    return txs[0]

def delete_transaction(self, id):
    tx = self.get_transaction(id)

    def go():
        self._conn.execute("DELETE FROM import_keys WHERE tx_id = ?", (id,))
        self._conn.execute("DELETE FROM tags WHERE tx_id = ?", (id,))
        self._conn.execute("DELETE FROM postings WHERE tx_id = ?", (id,))
        self._conn.execute("DELETE FROM transactions WHERE id = ?", (id,))
    self._write(go)
    return tx

# ------------------------------------------------------------------ rates
def set_rate(self, src, dst, rate_text, on):
    self._require()
    RateTable().set(src, dst, rate_text, on)

    def go():
        self._conn.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                           (src, dst, format_date(on), rate_text))
    self._write(go)

def remove_rate(self, src, dst, on):
    self._require()
    if not _is_date(on):
        raise ValidationError("invalid date %r" % (on,))
    rows = self._q("SELECT 1 FROM rates WHERE src = ? AND dst = ? AND on_date = ?", (src, dst, format_date(on)))
    if not rows:
        raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, format_date(on)))

    def go():
        self._conn.execute("DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?",
                           (src, dst, format_date(on)))
    self._write(go)

def rate_rows(self):
    self._require()
    return [(s, d, parse_date(o), t) for s, d, o, t in
            self._q("SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date")]

def rate_table(self):
    self._require()
    return self._build_rates()

# ---------------------------------------------------------------- budgets
def add_budget(self, budget):
    from tallybook.budgets import Budget
    self._require()
    if not isinstance(budget, Budget):
        raise ValidationError("not a budget: %r" % (budget,))
    if self._q("SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?",
               (budget.pattern, budget.period_kind)):
        raise ConflictError("a %s budget for %s already exists" % (budget.period_kind, budget.pattern))

    def go():
        self._conn.execute("INSERT INTO budgets (pattern, period_kind, minor, currency, start_date) "
                           "VALUES (?, ?, ?, ?, ?)", (budget.pattern, budget.period_kind, budget.amount.minor,
                                                      budget.amount.currency, format_date(budget.start)))
    self._write(go)
    return budget

def remove_budget(self, pattern, period_kind):
    self._require()
    found = [b for b in self.budgets() if b.pattern == pattern and b.period_kind == period_kind]
    if not found:
        raise NotFoundError("no %s budget for %s" % (period_kind, pattern))

    def go():
        self._conn.execute("DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind))
    self._write(go)
    return found[0]

def budgets(self):
    from tallybook.budgets import Budget
    self._require()
    return [Budget(p, k, Money(m, c), parse_date(s)) for p, k, m, c, s in
            self._q("SELECT pattern, period_kind, minor, currency, start_date FROM budgets "
                    "ORDER BY pattern, period_kind")]

# -------------------------------------------------------------- recurring
def add_recurring(self, rec):
    from tallybook.recurring import Recurring
    self._require()
    if not isinstance(rec, Recurring):
        raise ValidationError("not a recurring item: %r" % (rec,))
    if self._q("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)):
        raise ConflictError("recurring item %s already exists" % rec.name)

    def go():
        self._conn.execute("INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count, "
                           "materialized_through) VALUES (?, ?, ?, ?, ?, ?, NULL)",
                           (rec.name, str(rec.schedule), _template_to_json(rec.template),
                            format_date(rec.start), _ds(rec.end), rec.count))
    self._write(go)
    return rec

def _recurring_rows(self):
    from tallybook.recurring import Recurring
    out = []
    for name, sched, tmpl, start, end, count, through in self._q(
            "SELECT name, schedule, template, start_date, end_date, max_count, materialized_through "
            "FROM recurring ORDER BY name"):
        out.append((Recurring(name, sched, _template_from_json(tmpl), parse_date(start), _d(end), count),
                    _d(through)))
    return out

def recurring(self):
    self._require()
    return [r for r, _ in self._recurring_rows()]

def remove_recurring(self, name):
    self._require()
    found = [r for r, _ in self._recurring_rows() if r.name == name]
    if not found:
        raise NotFoundError("no recurring item %s" % (name,))

    def go():
        self._conn.execute("DELETE FROM recurring WHERE name = ?", (name,))
    self._write(go)
    return found[0]

def materialized_through(self, name):
    self._require()
    rows = self._q("SELECT materialized_through FROM recurring WHERE name = ?", (name,))
    if not rows:
        raise NotFoundError("no recurring item %s" % (name,))
    return _d(rows[0][0])

def materialize(self, upto=None, today=None):
    from tallybook.recurring import instantiate, occurrences
    self._require()
    for v in (upto, today):
        if v is not None and not _is_date(v):
            raise ValidationError("invalid date %r" % (v,))
    if upto is None and today is None:
        raise ValidationError("materialize needs a horizon: give upto or today")
    horizon = min(d for d in (upto, today) if d is not None)
    items = []
    for rec, through in self._recurring_rows():
        first = rec.start
        if through is not None:
            if through >= horizon:
                continue
            first = max(first, through + datetime.timedelta(days=1))
        for on in occurrences(rec, first, horizon):
            items.append((on, rec.name, instantiate(rec, on)))
    items.sort(key=lambda t: (t[0], t[1]))
    ledger = self._validator()
    prepared = [ledger.add(self._without_id(tx)) for _, _, tx in items]

    def go():
        nid = self._next_id()
        for stored in prepared:
            stored.id = nid
            nid += 1
            self._insert_tx(stored, ledger.chart)
        hz = format_date(horizon)
        self._conn.execute("UPDATE recurring SET materialized_through = ? WHERE materialized_through IS NULL "
                           "OR materialized_through < ?", (hz, hz))
        return prepared
    return self._write(go)

