# ------------------------------------------------------------- CSV import
def import_csv(self, text, profile, apply_rules=True):
    from tallybook.csvimport import ImportProfile, import_csv, parse_profile
    self._require()
    if isinstance(profile, ImportProfile):
        prof = profile
    elif isinstance(profile, str):
        if PROFILE_NAME_RE.fullmatch(profile):
            prof = parse_profile(self.profile_text(profile))
        else:
            prof = parse_profile(profile)
    else:
        raise ValidationError("invalid profile %r" % (profile,))
    rules = self.rules() if apply_rules else None
    existing = self._load_transactions()
    result = import_csv(text, prof, rules, existing)
    if result.errors:
        return ImportOutcome([], list(result.duplicates), list(result.errors))
    taken = {r[0] for r in self._q("SELECT key FROM import_keys")}
    keys = []
    for tx in result.transactions:
        first = tx.postings[0]
        base = "%s|%s|%s|%d %s" % (format_date(tx.date), tx.payee, first.account, first.amount.minor,
                                   first.amount.currency)
        n = 1
        while "%s|%d" % (base, n) in taken:
            n += 1
        key = "%s|%d" % (base, n)
        taken.add(key)
        keys.append(key)
    bulk = self.add_transactions(result.transactions, keys)
    return ImportOutcome(bulk.added, list(result.duplicates), [])

