def journal(self):
    from tallybook.journal import Journal
    self._require()
    accounts = self.accounts()
    rates = self.rate_rows()
    txs = []
    for tx in self._load_transactions():
        txs.append(Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None))
    return Journal(accounts=accounts, rates=rates, transactions=txs)

def load_journal(self, journal):
    self._require()
    chart = self._build_chart()
    rates = self._build_rates()
    new_accounts = []
    for acc in journal.accounts:
        stored = chart.add(acc.path, type=acc.type, currency=acc.currency, opened=acc.opened, note=acc.note)
        if acc.closed is not None:
            chart.close(acc.path, acc.closed)
        new_accounts.append(stored)
    for src, dst, on, text in journal.rates:
        rates.set(src, dst, text, on)
    ledger = Ledger(chart, rates)
    prepared = [ledger.add(self._without_id(tx)) for tx in journal.transactions]

    def go():
        for acc in new_accounts:
            self._conn.execute("INSERT OR REPLACE INTO accounts (path, type, currency, opened, note, closed) "
                               "VALUES (?, ?, ?, ?, ?, ?)", (acc.path, acc.type, acc.currency, _ds(acc.opened),
                                                             acc.note, _ds(acc.closed)))
        for src, dst, on, text in journal.rates:
            self._conn.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                               (src, dst, format_date(on), text))
        nid = self._next_id()
        for stored in prepared:
            stored.id = nid
            nid += 1
            self._insert_tx(stored, chart)
        return prepared
    return self._write(go)

