def check(self):
    self._require()
    problems = []
    for (res,) in self._q("PRAGMA integrity_check"):
        if res != "ok":
            problems.append("integrity check: %s" % res)
    for (tx_id,) in self._q("SELECT DISTINCT tx_id FROM postings WHERE tx_id NOT IN (SELECT id FROM transactions)"):
        problems.append("postings point to missing transaction %s" % tx_id)
    for (tx_id,) in self._q("SELECT DISTINCT tx_id FROM tags WHERE tx_id NOT IN (SELECT id FROM transactions)"):
        problems.append("tags point to missing transaction %s" % tx_id)
    for key, tx_id in self._q("SELECT key, tx_id FROM import_keys WHERE tx_id NOT IN (SELECT id FROM transactions)"):
        problems.append("import key %s points to missing transaction %s" % (key, tx_id))
    for (tx_id,) in self._q("SELECT id FROM transactions WHERE id NOT IN (SELECT tx_id FROM postings)"):
        problems.append("transaction %s has no postings" % tx_id)
    for tx_id, account in self._q("SELECT DISTINCT tx_id, account FROM postings "
                                  "WHERE account NOT IN (SELECT path FROM accounts)"):
        problems.append("transaction %s posts to unknown account %s" % (tx_id, account))
    for tx_id, cur, total in self._q("SELECT p.tx_id, p.currency, SUM(p.minor) FROM postings p "
                                     "JOIN transactions t ON t.id = p.tx_id "
                                     "GROUP BY p.tx_id, p.currency HAVING SUM(p.minor) != 0"):
        try:
            from tallybook.money import format_minor
            amount = "%s %s" % (format_minor(total, cur), cur)
        except TallybookError:
            amount = "%s %s" % (total, cur)
        problems.append("transaction %s does not balance: %s" % (tx_id, amount))
    return sorted(problems)

def backup(self, dest):
    self._require()
    fs = os.fspath(dest)
    if os.path.exists(fs):
        raise ConflictError("%s already exists" % fs)
    parent = os.path.dirname(os.path.abspath(fs))
    if not os.path.isdir(parent):
        raise NotFoundError("no such directory: %s" % (os.path.dirname(fs) or parent))
    try:
        target = sqlite3.connect(fs)
    except sqlite3.Error as e:
        raise ConflictError("cannot create %s: %s" % (fs, e)) from None
    try:
        self._conn.backup(target)
    finally:
        target.close()

