"""A small, strict command-line parser for tallybook."""

import re


class UsageError(Exception):
    """The command line itself is wrong (exit status 2)."""


class Fail(Exception):
    """The program refuses (exit status 1)."""

    def __init__(self, message, extra=()):
        super().__init__(message)
        self.extra = list(extra)


class HelpRequested(Exception):
    def __init__(self, text):
        super().__init__(text)
        self.text = text


class Command:
    def __init__(self, words, pos=(), opts=None, required=(), handler=None, book=True, summary=""):
        self.words = tuple(words)
        self.pos = list(pos)          # names; "X?" optional, "X..." one or more, "X*" zero or more
        self.opts = dict(opts or {})  # "--name": "value" | "flag" | "multi"
        self.required = set(required)
        self.handler = handler
        self.book = book
        self.summary = summary

    def usage(self):
        parts = ["usage: tallybook"] + list(self.words)
        for p in self.pos:
            if p.endswith("?"):
                parts.append("[%s]" % p[:-1])
            elif p.endswith("..."):
                parts.append("%s ..." % p[:-3])
            elif p.endswith("*"):
                parts.append("[%s ...]" % p[:-1])
            else:
                parts.append(p)
        for name, kind in self.opts.items():
            meta = OPTION_META.get(name, "VALUE")
            if kind == "flag":
                text = name
            else:
                text = "%s %s" % (name, meta)
            if name == "--posting":
                text = "-p POSTING"
            if kind == "multi":
                text = "[%s]..." % text
            elif name not in self.required:
                text = "[%s]" % text
            parts.append(text)
        return " ".join(parts)


OPTION_META = {
    "--currency": "CUR", "--open": "DATE", "--note": "TEXT", "--type": "TYPE", "--under": "PATH",
    "--on": "DATE", "--date": "DATE", "--narration": "TEXT", "--flag": "F", "--tag": "TAG", "--posting": "POSTING",
    "--query": "QUERY", "--limit": "N", "--offset": "N", "--format": "csv|json|journal", "--profile": "NAME",
    "--profile-file": "FILE", "--per": "KIND", "--start": "DATE", "--end": "DATE", "--count": "N",
    "--period": "PERIOD", "--upto": "DATE", "--as-of": "DATE", "--convert": "CUR", "--host": "HOST",
    "--port": "N", "--from": "D", "--to": "D", "--payee": "TEXT", "--amount": "MONEY", "--journal": "FILE",
    "--rules": "FILE",
}


def parse_command_args(cmd, args):
    """Read the arguments after the command words into (positionals, options)."""
    positional = []
    options = {}
    i = 0
    n = len(args)
    ended = False
    while i < n:
        a = args[i]
        i += 1
        if ended:
            positional.append(a)
            continue
        if a == "--":
            ended = True
            continue
        if a == "-p":
            name, value, has_value = "--posting", None, False
        elif a.startswith("--"):
            if "=" in a:
                name, value = a.split("=", 1)
                has_value = True
            else:
                name, value, has_value = a, None, False
        else:
            positional.append(a)
            continue
        kind = cmd.opts.get(name)
        if kind is None:
            raise UsageError("unknown option %s for '%s'" % (name, " ".join(cmd.words)))
        if kind == "flag":
            if has_value:
                raise UsageError("option %s takes no value" % name)
            if name in options:
                raise UsageError("option %s given twice" % name)
            options[name] = True
            continue
        if not has_value:
            if i >= n:
                raise UsageError("option %s needs a value" % (a if a != "-p" else "-p"))
            value = args[i]
            i += 1
        if kind == "multi":
            options.setdefault(name, []).append(value)
        else:
            if name in options:
                raise UsageError("option %s given twice" % name)
            options[name] = value
    # positionals
    out = {}
    j = 0
    for k, p in enumerate(cmd.pos):
        if p.endswith("..."):
            rest = positional[j:]
            if not rest:
                raise UsageError("missing argument %s" % p[:-3])
            out[p[:-3]] = rest
            j = len(positional)
        elif p.endswith("*"):
            out[p[:-1]] = positional[j:]
            j = len(positional)
        elif p.endswith("?"):
            if j < len(positional):
                out[p[:-1]] = positional[j]
                j += 1
            else:
                out[p[:-1]] = None
        else:
            if j >= len(positional):
                raise UsageError("missing argument %s" % p)
            out[p] = positional[j]
            j += 1
    if j < len(positional):
        raise UsageError("unexpected argument %r" % positional[j])
    for name in cmd.required:
        if name not in options:
            raise UsageError("missing required option %s" % name)
    return out, options


_INT_RE = re.compile(r"-?[0-9]{1,18}")


def whole(text, what="number", negative=False, low=None, high=None):
    if not isinstance(text, str) or not _INT_RE.fullmatch(text):
        raise Fail("invalid %s '%s': expected a whole number" % (what, text))
    value = int(text)
    if value < 0 and not negative:
        raise Fail("invalid %s '%s': must not be negative" % (what, text))
    if low is not None and value < low:
        raise Fail("invalid %s '%s': must be at least %d" % (what, text, low))
    if high is not None and value > high:
        raise Fail("invalid %s '%s': must be at most %d" % (what, text, high))
    return value
