REPORT_KINDS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def _run_report(ctx, kind, ledger, account, o):
    from tallybook import reports
    if kind == "trial-balance":
        rep = reports.trial_balance(ledger, _opt_date(o, "--as-of"))
    elif kind == "balance-sheet":
        as_of = _opt_date(o, "--as-of") or ctx.today
        rep = reports.balance_sheet(ledger, as_of, convert_to=o.get("--convert"), today=ctx.today)
    elif kind == "income-statement":
        period = _period(o["--period"]) if "--period" in o else _month_of(ctx.today)
        rep = reports.income_statement(ledger, period, convert_to=o.get("--convert"))
    elif kind == "cashflow":
        period = _period(o["--period"]) if "--period" in o else _month_of(ctx.today)
        rep = reports.cashflow(ledger, period)
    else:
        period = _period(o["--period"]) if "--period" in o else None
        rep = reports.register(ledger, account, period, rollup=bool(o.get("--rollup")))
    if o.get("--json"):
        _json(ctx, rep)
    else:
        ctx.write(reports.render_text(rep))


def _report_handler(kind):
    def handler(ctx, a, o):
        _check_report_values(kind, o)
        _run_report(ctx, kind, ctx.store().ledger(), a.get("ACCOUNT"), o)
    return handler


def _check_report_values(kind, o):
    # read values before touching the book
    if "--as-of" in o and kind in ("trial-balance", "balance-sheet"):
        _date(o["--as-of"])
    if "--period" in o and kind != "trial-balance" and kind != "balance-sheet":
        _period(o["--period"])


