def cmd_calc_date_periods(ctx, a, o):
    from tallybook.dates import DateError, periods
    start = _date(a["START"])
    end = _date(a["END"])
    step = a["STEP"]
    if step not in ("week", "month", "quarter", "year"):
        raise DateError("unknown step '%s': expected week, month, quarter or year" % step)
    if end >= start:
        days = (end - start).days
        months = (end.year - start.year) * 12 + end.month - start.month
        estimate = {"week": days // 7, "month": months, "quarter": months // 3, "year": end.year - start.year}[step]
        if estimate > 5002:
            raise Fail("too many periods: more than 5000")
    result = periods(start, end, step)
    if len(result) > 5000:
        raise Fail("too many periods: %d, more than 5000" % len(result))
    for p in result:
        ctx.print(p.label)


def cmd_calc_schedule(ctx, a, o):
    from tallybook.model import Posting, Transaction
    from tallybook.recurring import Recurring, occurrences, parse_schedule
    sched = parse_schedule(a["SCHEDULE"])
    frm = _date(o["--from"])
    to = _date(o["--to"])
    start = _opt_date(o, "--start") or frm
    end = _opt_date(o, "--end")
    count = whole(o["--count"], "count", negative=True) if "--count" in o else None
    tmpl = Transaction(start, "x", "", [], (), "*", None)
    rec = Recurring("calc", sched, tmpl, start, end, count)
    if (to - min(frm, start)).days > 40000:
        raise Fail("the window is too long: more than 40000 days")
    if to < frm:
        return
    for d in occurrences(rec, frm, to):
        ctx.print(d.isoformat())


