    if "--payee" in o:
        fields["payee"] = o["--payee"]
    if "--narration" in o:
        fields["narration"] = o["--narration"]
    if "--amount" in o:
        fields["amount"] = _money(o["--amount"])
    if "--date" in o:
        fields["date"] = _date(o["--date"])
    rules = parse_rules(_read_file(a["FILE"]))
    rule = rules.match(fields)
    if rule is None:
        ctx.print("no match")
        return
    result = rules.apply(fields)
    ctx.print("rule: %d" % rule.line)
    for key in ("account", "payee", "narration", "flag"):
        if key in result:
            value = result[key]
            ctx.print(("%s: %s" % (key, value)) if value != "" else "%s:" % key)
    if "tags" in result:
        ctx.print("tags: %s" % ",".join(result["tags"]))


