def cmd_calc_rate(ctx, a, o):
    on = _date(o["--on"])
    journal, ledger = _journal_ledger(o["--journal"])
    r = ledger.rates.rate(a["FROM"], a["TO"], on)
    ctx.print("%d/%d" % (r.numerator, r.denominator))


