BY_WORDS = {c.words: c for c in COMMANDS}
GROUPS = {}
for _c in COMMANDS:
    for _i in range(1, len(_c.words)):
        GROUPS.setdefault(_c.words[:_i], [])
        nxt = _c.words[_i]
        if nxt not in GROUPS[_c.words[:_i]]:
            GROUPS[_c.words[:_i]].append(nxt)


def main_usage():
    lines = ["usage: tallybook [--db FILE] [--today DATE] [--version] [-h] COMMAND [WORD] [ARGUMENTS]", "",
             "Double-entry bookkeeping on a book file.", "", "global options:",
             "  --db FILE      the book file (default: $TALLYBOOK_DB or tallybook.db)",
             "  --today DATE   what today is (default: the real date)",
             "  --version      print the version and stop",
             "  -h, --help     print this help and stop", "", "commands:"]
    for c in COMMANDS:
        lines.append("  %-30s %s" % (" ".join(c.words), c.summary))
    return "\n".join(lines) + "\n"


def group_usage(words):
    lines = ["usage: tallybook %s WORD ..." % " ".join(words), "", "words:"]
    for w in GROUPS[words]:
        full = words + (w,)
        if full in BY_WORDS:
            lines.append("  %-20s %s" % (w, BY_WORDS[full].summary))
        else:
            lines.append("  %-20s ..." % w)
    return "\n".join(lines) + "\n"


# ----------------------------------------------------------------------- running
def _write_stream(stream, text):
    if not text:
        return
    buf = getattr(stream, "buffer", None)
    if buf is not None:
        buf.write(text.encode("utf-8"))
        buf.flush()
    else:
        stream.write(text)
        stream.flush()


def flush_output(ctx):
    text = "".join(ctx.out)
    ctx.out = []
    try:
        _write_stream(sys.stdout, text)
    except BrokenPipeError:
        _silence_stdout()


def _silence_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, AttributeError, ValueError):
        pass


def _usage_error(message):
    _write_stream(sys.stderr, "%s: %s\nTry 'tallybook --help'.\n" % (PROG, message))
    return 2


def _fail(message, extra=()):
    message = str(message).replace("\n", " ")
    _write_stream(sys.stderr, "".join(["%s: %s\n" % (PROG, message)] + ["%s\n" % e for e in extra]))
    return 1


def _help(text):
    try:
        _write_stream(sys.stdout, text)
    except BrokenPipeError:
        _silence_stdout()
    return 0


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    argv = list(argv)
    try:
        return _main(argv)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except KeyboardInterrupt:
        return 130


def _main(argv):
    from tallybook.dates import DateError, parse_date
    db = None
    today = None
    seen = set()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("-h", "--help"):
            return _help(main_usage())
        if a == "--version":
            return _help("tallybook %s\n" % __version__)
        name, value = None, None
        if a.startswith("--db") or a.startswith("--today"):
            if a in ("--db", "--today"):
                name = a
                if i + 1 >= len(argv):
                    return _usage_error("option %s needs a value" % a)
                value = argv[i + 1]
                i += 2
            elif a.startswith("--db=") or a.startswith("--today="):
                name, value = a.split("=", 1)
                i += 1
            else:
                return _usage_error("unknown option %s" % a)
            if name in seen:
                return _usage_error("option %s given twice" % name)
            seen.add(name)
            if name == "--db":
                db = value
            else:
                try:
                    today = parse_date(value)
                except DateError as e:
                    return _fail(e.message)
            continue
        if a.startswith("-") and a != "-":
            return _usage_error("unknown option %s" % a)
        break
    rest = argv[i:]
    if not rest:
        return _usage_error("no command given")
    # resolve the command words
    words = ()
    j = 0
    while True:
        if j < len(rest) and words + (rest[j],) in BY_WORDS:
            words = words + (rest[j],)
            j += 1
            break
        if j < len(rest) and words + (rest[j],) in GROUPS:
            words = words + (rest[j],)
            j += 1
            continue
        # not a command
        if words in GROUPS:
            if j < len(rest) and rest[j] in ("-h", "--help"):
                return _help(group_usage(words))
            if j >= len(rest):
                return _usage_error("'%s' needs a word: %s" % (" ".join(words), ", ".join(GROUPS[words])))
            return _usage_error("unknown word '%s' for '%s'" % (rest[j], " ".join(words)))
        if j < len(rest):
            return _usage_error("unknown command '%s'" % rest[j])
        return _usage_error("no command given")
    cmd = BY_WORDS[words]
    args = rest[j:]
    for x in args:
        if x == "--":
            break
        if x in ("-h", "--help"):
            return _help(cmd.usage() + "\n")
    try:
        positional, options = parse_command_args(cmd, args)
    except UsageError as e:
        return _usage_error(str(e))
    if db is None:
        env = os.environ.get("TALLYBOOK_DB")
        db = env if env else "tallybook.db"
    ctx = Context(db, today)
    try:
        cmd.handler(ctx, positional, options)
    except UsageError as e:
        ctx.close()
        return _usage_error(str(e))
    except Fail as e:
        ctx.close()
        return _fail(e.args[0] if e.args else "failed", getattr(e, "extra", ()))
    except TallybookError as e:
        ctx.close()
        return _fail(e.message or e.__class__.__name__)
    except (OSError, ValueError, OverflowError, RecursionError) as e:
        ctx.close()
        if isinstance(e, BrokenPipeError):
            raise
        return _fail(str(e) or e.__class__.__name__)
    except Exception as e:  # never show a traceback
        ctx.close()
        return _fail("internal error: %s" % (str(e) or e.__class__.__name__))
    finally:
        ctx.close()
    if ctx.exit == 1 and ctx.out:
        flush_output(ctx)
        return 1
    flush_output(ctx)
    return ctx.exit

"""The tallybook command line."""

import datetime
import os
import sys

from tallybook import __version__
from tallybook.cli.args import Command, Fail, HelpRequested, UsageError, parse_command_args, whole
from tallybook.errors import NotFoundError, TallybookError

PROG = "tallybook"


# --------------------------------------------------------------------------- context
class Context:
    def __init__(self, db, today_arg):
        self.db = db
        self._today = today_arg
        self.out = []
        self.err = []
        self._store = None
        self.exit = 0

    @property
    def today(self):
        if self._today is None:
            self._today = datetime.date.today()
        return self._today

    def print(self, text=""):
        self.out.append(text + "\n")

    def write(self, text):
        self.out.append(text)

    def store(self, require=True):
        if self._store is None:
            from tallybook.storage import Store
            if not os.path.exists(self.db) and not os.path.isdir(self.db):
                raise Fail("no such database: %s (run `tallybook init`)" % self.db)
            try:
                self._store = Store.open(self.db)
            except NotFoundError:
                raise Fail("no such database: %s (run `tallybook init`)" % self.db) from None
        if require:
            self._store._require()
        return self._store

    def close(self):
        if self._store is not None:
            self._store.close()
            self._store = None


# ------------------------------------------------------------------------- helpers
def _date(text, what="date"):
    from tallybook.dates import parse_date
    return parse_date(text)


def _opt_date(opts, name, default=None):
    v = opts.get(name)
    return _date(v) if v is not None else default


def _period(text):
    from tallybook.dates import Period
    return Period.parse(text)


def _month_of(d):
    from tallybook.dates import period_containing
    return period_containing(d, "month")


def _money(text):
    from tallybook.money import Money
    return Money.parse(text)


def _json(ctx, value):
    from tallybook.export import to_json
    ctx.write(to_json(value))


def _table(ctx, headers, rows, align=None):
    from tallybook.export import render_table
    ctx.write(render_table(headers, rows, align))


def _read_file(name):
    if name == "-":
        data = sys.stdin.buffer.read() if hasattr(sys.stdin, "buffer") else sys.stdin.read().encode("utf-8")
    else:
        try:
            with open(name, "rb") as fh:
                data = fh.read()
        except OSError as e:
            raise Fail("cannot read %s: %s" % (name, e.strerror or e)) from None
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Fail("cannot read %s: not UTF-8 text" % ("standard input" if name == "-" else name)) from None


def _file_label(name):
    return "standard input" if name == "-" else name


def _read_journal(name):
    from tallybook.journal import JournalError, parse_journal
    text = _read_file(name)
    try:
        return parse_journal(text)
    except JournalError as e:
        raise Fail("%s: %s" % (_file_label(name), e.message)) from None


def parse_posting(text):
    from tallybook.model import Posting
    from tallybook.money import Money
    note = ""
    body = text
    if ";" in text:
        body, note = text.split(";", 1)
        note = note.strip()
    parts = body.split()
    if len(parts) == 1:
        return Posting(parts[0], None, note)
    if len(parts) == 3:
        return Posting(parts[0], Money.of(parts[1], parts[2]), note)
    raise Fail("invalid posting '%s': expected 'ACCOUNT [AMOUNT CURRENCY] [; note]'" % text)


def _build_tx(date, payee, opts):
    from tallybook.model import Transaction
    postings = [parse_posting(p) for p in opts.get("--posting", [])]
    return Transaction(date, payee, opts.get("--narration", ""), postings, tuple(opts.get("--tag", [])),
                       opts.get("--flag", "*"), None)


def _tx_dict(tx):
    from tallybook.export import transaction_to_dict
    return transaction_to_dict(tx)


def _money_dict(m):
    from tallybook.export import money_to_dict
    return money_to_dict(m)


def _list_transactions(ctx, txs, as_json):
    if as_json:
        _json(ctx, [_tx_dict(t) for t in txs])
        return
    if not txs:
        return
    rows = [[t.id if t.id is not None else "", t.date.isoformat(), t.flag, t.payee, t.narration,
             " ".join("#" + g for g in sorted(set(t.tags)))] for t in txs]
    _table(ctx, ["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll")


def _account_dict(a):
    return {"path": a.path, "type": a.type, "currency": a.currency,
            "opened": a.opened.isoformat() if a.opened else None,
            "closed": a.closed.isoformat() if a.closed else None, "note": a.note}


def _plural(n, word):
    return "%d %s" % (n, word)


# ------------------------------------------------------------------------ commands
def cmd_init(ctx, a, o):
    from tallybook.storage import LATEST_VERSION, Store
    if not os.path.exists(ctx.db) and not os.path.isdir(ctx.db):
        with Store.open(ctx.db, create=True) as s:
            ctx.print("created %s (version %d)" % (ctx.db, s.version))
        return
    with Store.open(ctx.db) as s:
        v = s.version
        if v < LATEST_VERSION:
            s.migrate()
            ctx.print("migrated %s from version %d to %d" % (ctx.db, v, s.version))
        else:
            ctx.print("%s is up to date (version %d)" % (ctx.db, v))


def cmd_db_version(ctx, a, o):
    ctx.print(str(ctx.store(require=False).version))


def cmd_db_migrate(ctx, a, o):
    s = ctx.store(require=False)
    applied = s.migrate()
    if not applied:
        ctx.print("database is up to date (version %d)" % s.version)
    for v in applied:
        ctx.print("applied version %d" % v)


def cmd_db_info(ctx, a, o):
    info = ctx.store().info()
    if o.get("--json"):
        _json(ctx, info)
        return
    for k in ("path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"):
        ctx.print("%s: %s" % (k, info[k]))


def cmd_db_check(ctx, a, o):
    problems = ctx.store().check()
    if not problems:
        ctx.print("ok")
        return
    for p in problems:
        ctx.print(p)
    ctx.exit = 1


def cmd_db_backup(ctx, a, o):
    ctx.store().backup(a["DEST"])
    ctx.print("backed up to %s" % a["DEST"])


def cmd_serve(ctx, a, o):
    host = o.get("--host", "127.0.0.1")
    port = whole(o["--port"], "port", high=65535) if "--port" in o else 8765
    today = ctx._today
    ctx.store()
