def _row_errors(errors):
    first = "%d rows could not be imported" % len(errors)
    return first, ["row %d: %s" % (n, m) for n, m in errors]


def cmd_import(ctx, a, o):
    has_name = "--profile" in o
    has_file = "--profile-file" in o
    if has_name == has_file:
        raise UsageError("give exactly one of --profile and --profile-file")
    from tallybook.csvimport import parse_profile
    if has_file:
        profile = parse_profile(_read_file(o["--profile-file"]))
    else:
        profile = o["--profile"]
    text = _read_file(a["FILE"])
    s = ctx.store()
    if not has_file:
        profile = parse_profile(s.profile_text(profile))
    outcome = s.import_csv(text, profile, apply_rules=not o.get("--no-rules"))
    if outcome.errors:
        first, lines = _row_errors(outcome.errors)
        raise Fail(first + ", nothing was imported", extra=lines)
    ctx.print("imported %s, %s" % (_plural(len(outcome.added), "transactions"),
                                   _plural(len(outcome.duplicates), "duplicates")))


