# ------------------------------------------------------------------ helpers
class _Answer(Exception):
    """An early answer (404, 405, 413, 415, 400 for a bad length)."""

    def __init__(self, status, message, headers=()):
        super().__init__(message)
        self.status = status
        self.message = message
        self.headers = list(headers)


class _Response:
    def __init__(self, status, body, ctype="application/json; charset=utf-8"):
        self.status = status
        self.body = body
        self.ctype = ctype


def _json(status, value):
    return _Response(status, to_json(value).encode("utf-8"))


def _text(text, ctype="text/plain; charset=utf-8"):
    return _Response(200, text.encode("utf-8"), ctype)


def _date_text(d):
    return None if d is None else "%04d-%02d-%02d" % (d.year, d.month, d.day)


def account_to_dict(acc):
    return {"path": acc.path, "type": acc.type, "currency": acc.currency, "opened": _date_text(acc.opened),
            "closed": _date_text(acc.closed), "note": acc.note}


def rate_to_dict(src, dst, on, text):
    return {"src": src, "dst": dst, "date": _date_text(on), "rate": text}


def budget_to_dict(b):
    return {"pattern": b.pattern, "period_kind": b.period_kind, "amount": money_to_dict(b.amount),
            "start": _date_text(b.start)}


def recurring_to_dict(rec):
    t = rec.template
    return {"name": rec.name, "schedule": str(rec.schedule), "start": _date_text(rec.start),
            "end": _date_text(rec.end), "count": rec.count,
            "template": {"payee": t.payee, "narration": t.narration, "flag": t.flag,
                         "tags": sorted(set(t.tags or ())),
                         "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                                      for p in t.postings]}}


class _Fields:
    """Reads the fields of a JSON object: unknown, missing and wrongly typed fields are errors."""

    def __init__(self, obj, allowed, where=""):
        if not isinstance(obj, dict):
            raise ValidationError("%sexpected a JSON object" % where)
        for k in obj:
            if k not in allowed:
                raise ValidationError("%sunknown field: %s" % (where, k))
        self.obj = obj
        self.where = where

    def get(self, name, kind=None, required=False):
        value = self.obj.get(name)
        if value is None:
            if required:
                raise ValidationError("%smissing field: %s" % (self.where, name))
            return None
        if kind is not None:
            ok = isinstance(value, kind) and not (kind in (int, (int,)) and isinstance(value, bool))
            if not ok:
                names = {str: "text", bool: "true or false", list: "a list", dict: "an object"}
                raise ValidationError("%sfield %s must be %s" % (self.where, name, names.get(kind, "valid")))
        return value

    def date(self, name, required=False):
        value = self.get(name, str, required)
        return None if value is None else parse_date(value)


def _money(value, where):
    if isinstance(value, str):
        return Money.parse(value)
    if isinstance(value, dict):
        if set(value) != {"amount", "currency"}:
            raise ValidationError("%s: an amount must be an object with exactly 'amount' and 'currency'" % where)
        if not isinstance(value["amount"], str) or not isinstance(value["currency"], str):
            raise ValidationError("%s: 'amount' and 'currency' must be text" % where)
        return Money.of(value["amount"], value["currency"])
    raise ValidationError("%s must be an amount object or text like '12.50 USD'" % where)


def _postings(raw):
    if not isinstance(raw, list):
        raise ValidationError("field postings must be a list")
    out = []
    for i, item in enumerate(raw, 1):
        where = "posting %d: " % i
        f = _Fields(item, ("account", "amount", "note"), where)
        account = f.get("account", str, True)
        amount = f.obj.get("amount")
        amount = None if amount is None else _money(amount, "posting %d amount" % i)
        note = f.get("note", str)
        out.append(Posting(account, amount, "" if note is None else note))
    return out


def _tags(f):
    tags = f.get("tags", list)
    if tags is None:
        return ()
    for t in tags:
        if not isinstance(t, str):
            raise ValidationError("field tags must be a list of text")
    return tuple(sorted(set(tags)))


def _transaction_from(obj):
    f = _Fields(obj, ("date", "payee", "narration", "flag", "tags", "postings"))
    d = f.date("date", True)
    payee = f.get("payee", str, True)
    narration = f.get("narration", str)
    flag = f.get("flag", str)
    tags = _tags(f)
    postings = _postings(f.get("postings", list, True))
    return Transaction(d, payee, "" if narration is None else narration, postings, tags,
                       "*" if flag is None else flag)


def _template_from(obj):
    f = _Fields(obj, ("payee", "narration", "flag", "tags", "postings"), "template: ")
    payee = f.get("payee", str, True)
    narration = f.get("narration", str)
    flag = f.get("flag", str)
    if flag is not None and flag not in ("*", "!"):
        raise ValidationError("template: invalid flag %r: expected '*' or '!'" % flag)
    tags = _tags(f)
    postings = _postings(f.get("postings", list, True))
    return Transaction(None, payee, "" if narration is None else narration, postings, tags,
                       "*" if flag is None else flag)


def _yes_no(text, name):
    low = text.lower()
    if low in ("true", "yes", "1"):
        return True
    if low in ("false", "no", "0"):
        return False
    raise ValidationError("invalid %s %r: expected true, false, yes, no, 1 or 0" % (name, text))


def _whole(text, name):
    if not re.fullmatch(r"[0-9]+", text) or int(text) > MAX_INT:
        raise ValidationError("invalid %s %r: expected a whole number of at least 0" % (name, text))
    return int(text)


def _need(query, name):
    if name not in query:
        raise ValidationError("missing query parameter: %s" % name)
    return query[name]


def _format(query, allowed):
    fmt = query.get("format", allowed[0])
    if fmt not in allowed:
        raise ValidationError("invalid format %r: expected %s" % (fmt, " or ".join(allowed)))
    return fmt


# ------------------------------------------------------------------- routes
_ROUTES = [
    (("health",), ("GET",), "health"),
    (("accounts",), ("GET", "POST"), "accounts"),
    (("accounts", None), ("GET",), "account"),
    (("accounts", None, "close"), ("POST",), "account_close"),
    (("transactions",), ("GET", "POST"), "transactions"),
    (("transactions", None), ("DELETE", "GET"), "transaction"),
    (("rates",), ("DELETE", "GET", "PUT"), "rates"),
    (("budgets",), ("DELETE", "GET", "POST"), "budgets"),
    (("budgets", "status"), ("GET",), "budget_status"),
    (("recurring",), ("DELETE", "GET", "POST"), "recurring"),
    (("recurring", "materialize"), ("POST",), "materialize"),
    (("import",), ("POST",), "import"),
    (("rules",), ("GET", "PUT"), "rules"),
    (("export",), ("GET",), "export"),
] + [(("reports", name), ("GET",), "report") for name in _REPORTS]


def _route(pieces):
    """The (verbs, handler name, captured pieces) of a path, or None."""
    for pattern, verbs, name in _ROUTES:
        if len(pattern) != len(pieces):
            continue
        captured = []
        for want, got in zip(pattern, pieces):
            if want is None:
                captured.append(got)
            elif want != got:
                break
        else:
            return verbs, name, captured, pieces
    return None


def _split_path(raw):
    raw = raw.split("#", 1)[0]
    path, _, qs = raw.partition("?")
    if not path.startswith("/"):
        return None, {}
    pieces = [unquote(p) for p in path[1:].split("/")]
    if any(p == "" for p in pieces):
        return None, {}
    query = dict(parse_qsl(qs, keep_blank_values=True))
    return pieces, query


def _content_type(header):
    if header is None:
        return None
    return header.split(";", 1)[0].strip().lower()


# ------------------------------------------------------------------ handler
class _App:
    def __init__(self, db_path, today):
        self.db_path = db_path
        self.today_value = today

    def today(self):
        return self.today_value if self.today_value is not None else datetime.date.today()

    # every handler gets (store, verb, captured, pieces, query, body) and returns a _Response
    def health(self, s, verb, cap, pieces, q, body):
        return _json(200, {"status": "ok", "version": tallybook.__version__, "schema_version": s.version})

    def accounts(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            include = _yes_no(q["include_closed"], "include_closed") if "include_closed" in q else True
            accs = s.accounts(type=q.get("type"), under=q.get("under"), currency=q.get("currency"),
                              include_closed=include)
            return _json(200, [account_to_dict(a) for a in accs])
        f = _Fields(body, ("path", "type", "currency", "opened", "note"))
        path = f.get("path", str, True)
        acc = s.add_account(path, type=f.get("type", str), currency=f.get("currency", str),
                            opened=f.date("opened"), note=f.get("note", str) or "")
        return _json(201, account_to_dict(acc))

    def account(self, s, verb, cap, pieces, q, body):
        return _json(200, account_to_dict(s.get_account(cap[0])))

    def account_close(self, s, verb, cap, pieces, q, body):
        f = _Fields(body, ("on",))
        on = f.date("on")
        acc = s.close_account(cap[0], on if on is not None else self.today())
        return _json(200, account_to_dict(acc))

    def transactions(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            text = q.get("q") or None
            limit = _whole(q["limit"], "limit") if "limit" in q else None
            offset = _whole(q["offset"], "offset") if "offset" in q else 0
            total = s.count_transactions(text)
            items = s.transactions(text, limit=limit, offset=offset)
            return _json(200, {"items": [transaction_to_dict(t) for t in items], "total": total,
                               "limit": limit, "offset": offset})
        tx = _transaction_from(body)
        return _json(201, transaction_to_dict(s.add_transaction(tx)))

    def transaction(self, s, verb, cap, pieces, q, body):
        text = cap[0]
        if not re.fullmatch(r"[0-9]+", text):
            raise NotFoundError("no such transaction %s" % text)
        tid = int(text)
        if verb == "DELETE":
            return _json(200, transaction_to_dict(s.delete_transaction(tid)))
        return _json(200, transaction_to_dict(s.get_transaction(tid)))

    def rates(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            return _json(200, [rate_to_dict(*r) for r in s.rate_rows()])
        if verb == "DELETE":
            src, dst = _need(q, "src"), _need(q, "dst")
            on = parse_date(_need(q, "date"))
            text = None
            for r in s.rate_rows():
                if r[0] == src and r[1] == dst and r[2] == on:
                    text = r[3]
            s.remove_rate(src, dst, on)
            return _json(200, rate_to_dict(src, dst, on, text))
        f = _Fields(body, ("src", "dst", "date", "rate"))
        src = f.get("src", str, True)
        dst = f.get("dst", str, True)
        on = f.date("date", True)
        rate = f.get("rate", str, True)
        s.set_rate(src, dst, rate, on)
        return _json(200, rate_to_dict(src, dst, on, rate))

    def budgets(self, s, verb, cap, pieces, q, body):
        from tallybook.budgets import Budget
        if verb == "GET":
            return _json(200, [budget_to_dict(b) for b in s.budgets()])
        if verb == "DELETE":
            pattern, kind = _need(q, "pattern"), _need(q, "period_kind")
            return _json(200, budget_to_dict(s.remove_budget(pattern, kind)))
        f = _Fields(body, ("pattern", "period_kind", "amount", "start"))
        pattern = f.get("pattern", str, True)
        kind = f.get("period_kind", str, True)
        amount = _money(f.get("amount", None, True), "amount")
        start = f.date("start", True)
        return _json(201, budget_to_dict(s.add_budget(Budget(pattern, kind, amount, start))))

    def budget_status(self, s, verb, cap, pieces, q, body):
        from tallybook.budgets import budget_status
        period = Period.parse(_need(q, "period"))
        lines = budget_status(s.budgets(), s.ledger(), period)
        return _json(200, [line.to_dict() for line in lines])

    def recurring(self, s, verb, cap, pieces, q, body):
        from tallybook.recurring import Recurring
        if verb == "GET":
            return _json(200, [recurring_to_dict(r) for r in s.recurring()])
        if verb == "DELETE":
            return _json(200, recurring_to_dict(s.remove_recurring(_need(q, "name"))))
        f = _Fields(body, ("name", "schedule", "start", "end", "count", "template"))
        name = f.get("name", None, True)
        schedule = f.get("schedule", str, True)
        start = f.date("start", True)
        end = f.date("end")
        count = f.get("count")
        template = _template_from(f.get("template", dict, True))
        rec = Recurring(name, schedule, template, start, end=end, count=count)
        return _json(201, recurring_to_dict(s.add_recurring(rec)))

    def materialize(self, s, verb, cap, pieces, q, body):
        f = _Fields(body, ("upto",))
        upto = f.date("upto")
        added = s.materialize(upto=upto, today=self.today())
        return _json(200, {"added": [transaction_to_dict(t) for t in added]})

    def import_(self, s, verb, cap, pieces, q, body):
        if isinstance(body, dict):
            f = _Fields(body, ("csv", "profile", "apply_rules"))
            text = f.get("csv", str, True)
            profile = f.get("profile", str, True)
            apply_rules = f.get("apply_rules", bool)
            apply_rules = True if apply_rules is None else apply_rules
        else:
            text = body
            profile = _need(q, "profile")
            apply_rules = _yes_no(q["apply_rules"], "apply_rules") if "apply_rules" in q else True
        outcome = s.import_csv(text, profile, apply_rules=apply_rules)
        if outcome.errors:
            raise ValidationError("import failed: " + "; ".join("row %s: %s" % (row, msg)
                                                                for row, msg in outcome.errors))
        return _json(200, {"added": [transaction_to_dict(t) for t in outcome.added],
                           "duplicates": [transaction_to_dict(t) for t in outcome.duplicates]})

    def rules(self, s, verb, cap, pieces, q, body):
        if verb == "PUT":
            f = _Fields(body, ("rules",))
            s.set_rules(f.get("rules", str, True))
        return _json(200, {"rules": s.rules_text()})

    def export(self, s, verb, cap, pieces, q, body):
        fmt = _format(q, ("json", "csv", "journal"))
        if fmt == "journal":
            from tallybook.journal import format_journal
            return _text(format_journal(s.journal()))
        txs = s.transactions()
        if fmt == "csv":
            return _text(transactions_to_csv(txs), "text/csv; charset=utf-8")
        return _json(200, [transaction_to_dict(t) for t in txs])

    def report(self, s, verb, cap, pieces, q, body):
        from tallybook import reports
        name = pieces[1]
        fmt = _format(q, ("json", "text"))

        def date_param(key):
            return parse_date(q[key]) if key in q else None

        def period_param(required):
            if required:
                return Period.parse(_need(q, "period"))
            return Period.parse(q["period"]) if "period" in q else None

        convert_to = q.get("convert_to")
        if name == "trial-balance":
            as_of = date_param("as_of")
            report = reports.trial_balance(s.ledger(), as_of)
        elif name == "balance-sheet":
            as_of = date_param("as_of")
            report = reports.balance_sheet(s.ledger(), as_of, convert_to, today=self.today())
        elif name == "income-statement":
            period = period_param(True)
            report = reports.income_statement(s.ledger(), period, convert_to)
        elif name == "cashflow":
            period = period_param(True)
            report = reports.cashflow(s.ledger(), period)
        else:
            account = _need(q, "account")
            period = period_param(False)
            rollup = _yes_no(q["rollup"], "rollup") if "rollup" in q else False
            report = reports.register(s.ledger(), account, period, rollup)
        if fmt == "text":
            return _text(reports.render_text(report))
        return _json(200, report)


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "tallybook/" + tallybook.__version__
    sys_version = ""
    app = None  # set on a subclass by make_server

    def log_message(self, format, *args):
        pass

    def __getattr__(self, name):
        # every verb, known or not, goes through the same dispatcher
        if name.startswith("do_"):
            return self._dispatch
        raise AttributeError(name)

    # ---------------------------------------------------------------- output
    def _send(self, status, body, ctype="application/json; charset=utf-8", headers=()):
        self.close_connection = True
        try:
            self.send_response(status)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(body)))
            for k, v in headers:
                self.send_header(k, v)
            self.send_header("Connection", "close")
            self.end_headers()
            if self.command != "HEAD" and body:
                self.wfile.write(body)
            self.wfile.flush()
        except (OSError, ValueError):
            pass

    def _send_error_json(self, status, message, headers=()):
        self._send(status, to_json({"error": message or "error"}).encode("utf-8"), headers=headers)

    def send_error(self, code, message=None, explain=None):
        # used by http.server itself for request lines it cannot read
        if not message:
            message = {400: "bad request", 414: "request line too long", 431: "request headers too large",
                       505: "HTTP version not supported"}.get(code, "request error %d" % code)
        if code == 501:
            code = 400
        if self.request_version == "HTTP/0.9":  # always answer with a status line and headers
            self.request_version = "HTTP/1.0"
        self._send_error_json(code, message)

    # ------------------------------------------------------------------ body
    def _drain(self, n):
        while n > 0:
            chunk = self.rfile.read(min(n, 65536))
            if not chunk:
                break
            n -= len(chunk)

    def _read_body(self):
        raw = self.headers.get("Content-Length")
        if raw is None:
            return b""
        raw = raw.strip()
        if not re.fullmatch(r"[0-9]+", raw):
            raise _Answer(400, "invalid Content-Length %r" % raw)
        n = int(raw)
        if n > MAX_BODY:
            if n <= _DRAIN_LIMIT:
                self._drain(n)
            raise _Answer(413, "request body too large: %d bytes, at most %d" % (n, MAX_BODY))
        data = b""
        while len(data) < n:
            chunk = self.rfile.read(n - len(data))
            if not chunk:
                break
            data += chunk
        return data

    # -------------------------------------------------------------- dispatch
    def _dispatch(self):
        try:
            response = self._handle()
        except _Answer as a:
            self._send_error_json(a.status, a.message, a.headers)
            return
        except TallybookError as e:
            self._send_error_json(_STATUS.get(e.code, 400), e.message or e.code)
            return
        except Exception as e:  # anything unexpected: a 500, nothing printed
            self._send_error_json(500, "internal error: %s" % (str(e) or type(e).__name__))
            return
        self._send(response.status, response.body, response.ctype)

    def _handle(self):
        verb = self.command
        pieces, query = _split_path(self.path)
        found = _route(pieces) if pieces is not None else None
        if found is None:
            self._read_body_quietly()
            raise _Answer(404, "no such path: %s" % self.path.split("?", 1)[0].split("#", 1)[0])
        verbs, name, captured, pieces = found
        if verb not in verbs:
            self._read_body_quietly()
            raise _Answer(405, "method %s not allowed here" % verb, [("Allow", ", ".join(sorted(verbs)))])
        data = self._read_body()
        body = None
        if verb in ("POST", "PUT"):
            ctype = _content_type(self.headers.get("Content-Type"))
            if name == "import":
                if not data:
                    body = ""
                elif ctype in ("text/csv", "text/plain"):
                    body = self._decode(data)
                elif ctype == "application/json":
                    body = self._parse_json(data)
                else:
                    raise _Answer(415, "unsupported content type %s: send application/json, text/csv or "
                                       "text/plain" % (ctype or "(none)"))
            else:
                if data and ctype != "application/json":
                    raise _Answer(415, "unsupported content type %s: send application/json" % (ctype or "(none)"))
                body = self._parse_json(data) if data else {}
        app = self.app
        method = getattr(app, "import_" if name == "import" else name)
        store = Store.open(app.db_path)
        try:
            return method(store, verb, captured, pieces, query, body)
        finally:
            store.close()

    def _read_body_quietly(self):
        try:
            self._read_body()
        except _Answer:
            pass

    @staticmethod
    def _decode(data):
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as e:
            raise ParseError("the body is not valid UTF-8: %s" % e) from None

    def _parse_json(self, data):
        text = self._decode(data)
        try:
            value = json.loads(text)
        except ValueError as e:
            raise ParseError("the body is not valid JSON: %s" % e) from None
        if not isinstance(value, dict):
            raise ValidationError("the body must be a JSON object")
        return value


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def handle_error(self, request, client_address):
        pass


def make_server(db_path, host="127.0.0.1", port=0, today=None):
    """Check the book and bind a server for it (not yet serving). Raises the storage error for a bad book."""
    if today is not None and (not isinstance(today, datetime.date) or isinstance(today, datetime.datetime)):
        raise ValidationError("invalid today %r: expected a date" % (today,))
    if not is_int(port) or not 0 <= port <= 65535:
        raise ValidationError("invalid port %r: expected 0 to 65535" % (port,))
    store = Store.open(db_path)
    try:
        store.info()
    finally:
        store.close()
    handler = type("Handler", (_Handler,), {"app": _App(db_path, today)})
    try:
        return _Server((host, port), handler)
    except OSError as e:
        raise ConflictError("cannot listen on %s:%s: %s" % (host, port, e.strerror or e)) from None


def serve(db_path, host="127.0.0.1", port=0, today=None):
    """Serve the book at db_path until SIGINT or SIGTERM; returns 0 (the exit status)."""
    server = make_server(db_path, host, port, today)
    previous = {}
    stopping = []

    def stop(signum, frame):
        if not stopping:
            stopping.append(signum)
            # shutdown() waits for serve_forever to finish, so it must run in another thread
            threading.Thread(target=server.shutdown, daemon=True).start()

    try:
        if threading.current_thread() is threading.main_thread():
            for sig in (signal.SIGINT, signal.SIGTERM):
                previous[sig] = signal.signal(sig, stop)
        sys.stdout.write("tallybook listening on http://%s:%d\n" % (host, server.server_address[1]))
        sys.stdout.flush()
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
    finally:
        server.server_close()
        for sig, handler in previous.items():
            signal.signal(sig, handler)
    return 0

"""The tallybook web API: JSON over HTTP on top of a book file (standard library only)."""

import datetime
import json
import re
import signal
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qsl, unquote

import tallybook
from tallybook.dates import Period, parse_date
from tallybook.errors import ConflictError, NotFoundError, ParseError, TallybookError, ValidationError, is_int
from tallybook.export import money_to_dict, to_json, transaction_to_dict, transactions_to_csv
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.storage import Store

__all__ = ["serve", "make_server"]

MAX_BODY = 1048576
MAX_INT = 9223372036854775807
_DRAIN_LIMIT = 256 * MAX_BODY
_STATUS = {"parse": 400, "validation": 400, "not_found": 404, "conflict": 409}
_REPORTS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


# ------------------------------------------------------------------ helpers
class _Answer(Exception):
    """An early answer (404, 405, 413, 415, 400 for a bad length)."""

    def __init__(self, status, message, headers=()):
        super().__init__(message)
        self.status = status
        self.message = message
        self.headers = list(headers)


class _Response:
    def __init__(self, status, body, ctype="application/json; charset=utf-8"):
        self.status = status
        self.body = body
        self.ctype = ctype


def _json(status, value):
    return _Response(status, to_json(value).encode("utf-8"))


def _text(text, ctype="text/plain; charset=utf-8"):
    return _Response(200, text.encode("utf-8"), ctype)


def _date_text(d):
    return None if d is None else "%04d-%02d-%02d" % (d.year, d.month, d.day)


def account_to_dict(acc):
    return {"path": acc.path, "type": acc.type, "currency": acc.currency, "opened": _date_text(acc.opened),
            "closed": _date_text(acc.closed), "note": acc.note}


def rate_to_dict(src, dst, on, text):
    return {"src": src, "dst": dst, "date": _date_text(on), "rate": text}


def budget_to_dict(b):
    return {"pattern": b.pattern, "period_kind": b.period_kind, "amount": money_to_dict(b.amount),
            "start": _date_text(b.start)}


def recurring_to_dict(rec):
    t = rec.template
    return {"name": rec.name, "schedule": str(rec.schedule), "start": _date_text(rec.start),
            "end": _date_text(rec.end), "count": rec.count,
            "template": {"payee": t.payee, "narration": t.narration, "flag": t.flag,
                         "tags": sorted(set(t.tags or ())),
                         "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                                      for p in t.postings]}}


class _Fields:
    """Reads the fields of a JSON object: unknown, missing and wrongly typed fields are errors."""

    def __init__(self, obj, allowed, where=""):
        if not isinstance(obj, dict):
            raise ValidationError("%sexpected a JSON object" % where)
        for k in obj:
            if k not in allowed:
                raise ValidationError("%sunknown field: %s" % (where, k))
        self.obj = obj
        self.where = where

    def get(self, name, kind=None, required=False):
        value = self.obj.get(name)
        if value is None:
            if required:
                raise ValidationError("%smissing field: %s" % (self.where, name))
            return None
        if kind is not None:
            ok = isinstance(value, kind) and not (kind in (int, (int,)) and isinstance(value, bool))
            if not ok:
                names = {str: "text", bool: "true or false", list: "a list", dict: "an object"}
                raise ValidationError("%sfield %s must be %s" % (self.where, name, names.get(kind, "valid")))
        return value

    def date(self, name, required=False):
        value = self.get(name, str, required)
        return None if value is None else parse_date(value)


def _money(value, where):
    if isinstance(value, str):
        return Money.parse(value)
    if isinstance(value, dict):
        if set(value) != {"amount", "currency"}:
            raise ValidationError("%s: an amount must be an object with exactly 'amount' and 'currency'" % where)
        if not isinstance(value["amount"], str) or not isinstance(value["currency"], str):
            raise ValidationError("%s: 'amount' and 'currency' must be text" % where)
        return Money.of(value["amount"], value["currency"])
    raise ValidationError("%s must be an amount object or text like '12.50 USD'" % where)


def _postings(raw):
    if not isinstance(raw, list):
        raise ValidationError("field postings must be a list")
    out = []
    for i, item in enumerate(raw, 1):
        where = "posting %d: " % i
        f = _Fields(item, ("account", "amount", "note"), where)
        account = f.get("account", str, True)
        amount = f.obj.get("amount")
        amount = None if amount is None else _money(amount, "posting %d amount" % i)
        note = f.get("note", str)
        out.append(Posting(account, amount, "" if note is None else note))
    return out


def _tags(f):
    tags = f.get("tags", list)
    if tags is None:
        return ()
    for t in tags:
        if not isinstance(t, str):
            raise ValidationError("field tags must be a list of text")
    return tuple(sorted(set(tags)))


def _transaction_from(obj):
    f = _Fields(obj, ("date", "payee", "narration", "flag", "tags", "postings"))
    d = f.date("date", True)
    payee = f.get("payee", str, True)
    narration = f.get("narration", str)
    flag = f.get("flag", str)
    tags = _tags(f)
    postings = _postings(f.get("postings", list, True))
    return Transaction(d, payee, "" if narration is None else narration, postings, tags,
                       "*" if flag is None else flag)


def _template_from(obj):
    f = _Fields(obj, ("payee", "narration", "flag", "tags", "postings"), "template: ")
    payee = f.get("payee", str, True)
    narration = f.get("narration", str)
    flag = f.get("flag", str)
    if flag is not None and flag not in ("*", "!"):
        raise ValidationError("template: invalid flag %r: expected '*' or '!'" % flag)
    tags = _tags(f)
    postings = _postings(f.get("postings", list, True))
    return Transaction(None, payee, "" if narration is None else narration, postings, tags,
                       "*" if flag is None else flag)


def _yes_no(text, name):
    low = text.lower()
    if low in ("true", "yes", "1"):
        return True
    if low in ("false", "no", "0"):
        return False
    raise ValidationError("invalid %s %r: expected true, false, yes, no, 1 or 0" % (name, text))


def _whole(text, name):
    if not re.fullmatch(r"[0-9]+", text) or int(text) > MAX_INT:
        raise ValidationError("invalid %s %r: expected a whole number of at least 0" % (name, text))
    return int(text)


def _need(query, name):
    if name not in query:
        raise ValidationError("missing query parameter: %s" % name)
    return query[name]


def _format(query, allowed):
    fmt = query.get("format", allowed[0])
    if fmt not in allowed:
        raise ValidationError("invalid format %r: expected %s" % (fmt, " or ".join(allowed)))
    return fmt


# ------------------------------------------------------------------- routes
_ROUTES = [
    (("health",), ("GET",), "health"),
    (("accounts",), ("GET", "POST"), "accounts"),
    (("accounts", None), ("GET",), "account"),
    (("accounts", None, "close"), ("POST",), "account_close"),
    (("transactions",), ("GET", "POST"), "transactions"),
    (("transactions", None), ("DELETE", "GET"), "transaction"),
    (("rates",), ("DELETE", "GET", "PUT"), "rates"),
    (("budgets",), ("DELETE", "GET", "POST"), "budgets"),
    (("budgets", "status"), ("GET",), "budget_status"),
    (("recurring",), ("DELETE", "GET", "POST"), "recurring"),
    (("recurring", "materialize"), ("POST",), "materialize"),
    (("import",), ("POST",), "import"),
    (("rules",), ("GET", "PUT"), "rules"),
    (("export",), ("GET",), "export"),
] + [(("reports", name), ("GET",), "report") for name in _REPORTS]


def _route(pieces):
    """The (verbs, handler name, captured pieces) of a path, or None."""
    for pattern, verbs, name in _ROUTES:
        if len(pattern) != len(pieces):
            continue
        captured = []
        for want, got in zip(pattern, pieces):
            if want is None:
                captured.append(got)
            elif want != got:
                break
        else:
            return verbs, name, captured, pieces
    return None


def _split_path(raw):
    raw = raw.split("#", 1)[0]
    path, _, qs = raw.partition("?")
    if not path.startswith("/"):
        return None, {}
    pieces = [unquote(p) for p in path[1:].split("/")]
    if any(p == "" for p in pieces):
        return None, {}
    query = dict(parse_qsl(qs, keep_blank_values=True))
    return pieces, query


def _content_type(header):
    if header is None:
        return None
    return header.split(";", 1)[0].strip().lower()


# ------------------------------------------------------------------ handler
class _App:
    def __init__(self, db_path, today):
        self.db_path = db_path
        self.today_value = today

    def today(self):
        return self.today_value if self.today_value is not None else datetime.date.today()

    # every handler gets (store, verb, captured, pieces, query, body) and returns a _Response
    def health(self, s, verb, cap, pieces, q, body):
        return _json(200, {"status": "ok", "version": tallybook.__version__, "schema_version": s.version})

    def accounts(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            include = _yes_no(q["include_closed"], "include_closed") if "include_closed" in q else True
            accs = s.accounts(type=q.get("type"), under=q.get("under"), currency=q.get("currency"),
                              include_closed=include)
            return _json(200, [account_to_dict(a) for a in accs])
        f = _Fields(body, ("path", "type", "currency", "opened", "note"))
        path = f.get("path", str, True)
        acc = s.add_account(path, type=f.get("type", str), currency=f.get("currency", str),
                            opened=f.date("opened"), note=f.get("note", str) or "")
        return _json(201, account_to_dict(acc))

    def account(self, s, verb, cap, pieces, q, body):
        return _json(200, account_to_dict(s.get_account(cap[0])))

    def account_close(self, s, verb, cap, pieces, q, body):
        f = _Fields(body, ("on",))
        on = f.date("on")
        acc = s.close_account(cap[0], on if on is not None else self.today())
        return _json(200, account_to_dict(acc))

    def transactions(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            text = q.get("q") or None
            limit = _whole(q["limit"], "limit") if "limit" in q else None
            offset = _whole(q["offset"], "offset") if "offset" in q else 0
            total = s.count_transactions(text)
            items = s.transactions(text, limit=limit, offset=offset)
            return _json(200, {"items": [transaction_to_dict(t) for t in items], "total": total,
                               "limit": limit, "offset": offset})
        tx = _transaction_from(body)
        return _json(201, transaction_to_dict(s.add_transaction(tx)))

    def transaction(self, s, verb, cap, pieces, q, body):
        text = cap[0]
        if not re.fullmatch(r"[0-9]+", text):
            raise NotFoundError("no such transaction %s" % text)
        tid = int(text)
        if verb == "DELETE":
            return _json(200, transaction_to_dict(s.delete_transaction(tid)))
        return _json(200, transaction_to_dict(s.get_transaction(tid)))

    def rates(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            return _json(200, [rate_to_dict(*r) for r in s.rate_rows()])
        if verb == "DELETE":
            src, dst = _need(q, "src"), _need(q, "dst")
            on = parse_date(_need(q, "date"))
            text = None
            for r in s.rate_rows():
                if r[0] == src and r[1] == dst and r[2] == on:
                    text = r[3]
            s.remove_rate(src, dst, on)
            return _json(200, rate_to_dict(src, dst, on, text))
        f = _Fields(body, ("src", "dst", "date", "rate"))
        src = f.get("src", str, True)
        dst = f.get("dst", str, True)
        on = f.date("date", True)
        rate = f.get("rate", str, True)
        s.set_rate(src, dst, rate, on)
        return _json(200, rate_to_dict(src, dst, on, rate))

    def budgets(self, s, verb, cap, pieces, q, body):
        from tallybook.budgets import Budget
        if verb == "GET":
            return _json(200, [budget_to_dict(b) for b in s.budgets()])
        if verb == "DELETE":
            pattern, kind = _need(q, "pattern"), _need(q, "period_kind")
            return _json(200, budget_to_dict(s.remove_budget(pattern, kind)))
        f = _Fields(body, ("pattern", "period_kind", "amount", "start"))
        pattern = f.get("pattern", str, True)
        kind = f.get("period_kind", str, True)
        amount = _money(f.get("amount", None, True), "amount")
        start = f.date("start", True)
        return _json(201, budget_to_dict(s.add_budget(Budget(pattern, kind, amount, start))))

    def budget_status(self, s, verb, cap, pieces, q, body):
        from tallybook.budgets import budget_status
        period = Period.parse(_need(q, "period"))
        lines = budget_status(s.budgets(), s.ledger(), period)
        return _json(200, [line.to_dict() for line in lines])

    def recurring(self, s, verb, cap, pieces, q, body):
        from tallybook.recurring import Recurring
        if verb == "GET":
            return _json(200, [recurring_to_dict(r) for r in s.recurring()])
        if verb == "DELETE":
            return _json(200, recurring_to_dict(s.remove_recurring(_need(q, "name"))))
        f = _Fields(body, ("name", "schedule", "start", "end", "count", "template"))
        name = f.get("name", None, True)
        schedule = f.get("schedule", str, True)
        start = f.date("start", True)
        end = f.date("end")
        count = f.get("count")
        template = _template_from(f.get("template", dict, True))
        rec = Recurring(name, schedule, template, start, end=end, count=count)
        return _json(201, recurring_to_dict(s.add_recurring(rec)))

    def materialize(self, s, verb, cap, pieces, q, body):
        f = _Fields(body, ("upto",))
        upto = f.date("upto")
        added = s.materialize(upto=upto, today=self.today())
        return _json(200, {"added": [transaction_to_dict(t) for t in added]})

    def import_(self, s, verb, cap, pieces, q, body):
        if isinstance(body, dict):
            f = _Fields(body, ("csv", "profile", "apply_rules"))
            text = f.get("csv", str, True)
            profile = f.get("profile", str, True)
            apply_rules = f.get("apply_rules", bool)
            apply_rules = True if apply_rules is None else apply_rules
        else:
            text = body
            profile = _need(q, "profile")
            apply_rules = _yes_no(q["apply_rules"], "apply_rules") if "apply_rules" in q else True
        outcome = s.import_csv(text, profile, apply_rules=apply_rules)
        if outcome.errors:
            raise ValidationError("import failed: " + "; ".join("row %s: %s" % (row, msg)
                                                                for row, msg in outcome.errors))
        return _json(200, {"added": [transaction_to_dict(t) for t in outcome.added],
                           "duplicates": [transaction_to_dict(t) for t in outcome.duplicates]})

    def rules(self, s, verb, cap, pieces, q, body):
        if verb == "PUT":
            f = _Fields(body, ("rules",))
            s.set_rules(f.get("rules", str, True))
        return _json(200, {"rules": s.rules_text()})

    def export(self, s, verb, cap, pieces, q, body):
        fmt = _format(q, ("json", "csv", "journal"))
        if fmt == "journal":
            from tallybook.journal import format_journal
            return _text(format_journal(s.journal()))
        txs = s.transactions()
        if fmt == "csv":
            return _text(transactions_to_csv(txs), "text/csv; charset=utf-8")
        return _json(200, [transaction_to_dict(t) for t in txs])

    def report(self, s, verb, cap, pieces, q, body):
        from tallybook import reports
        name = pieces[1]
        fmt = _format(q, ("json", "text"))

        def date_param(key):
            return parse_date(q[key]) if key in q else None

        def period_param(required):
            if required:
                return Period.parse(_need(q, "period"))
            return Period.parse(q["period"]) if "period" in q else None

        convert_to = q.get("convert_to")
        if name == "trial-balance":
            as_of = date_param("as_of")
            report = reports.trial_balance(s.ledger(), as_of)
        elif name == "balance-sheet":
            as_of = date_param("as_of")
            report = reports.balance_sheet(s.ledger(), as_of, convert_to, today=self.today())
        elif name == "income-statement":
            period = period_param(True)
            report = reports.income_statement(s.ledger(), period, convert_to)
        elif name == "cashflow":
            period = period_param(True)
            report = reports.cashflow(s.ledger(), period)
        else:
            account = _need(q, "account")
            period = period_param(False)
            rollup = _yes_no(q["rollup"], "rollup") if "rollup" in q else False
            report = reports.register(s.ledger(), account, period, rollup)
        if fmt == "text":
            return _text(reports.render_text(report))
        return _json(200, report)


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "tallybook/" + tallybook.__version__
    sys_version = ""
    app = None  # set on a subclass by make_server

    def log_message(self, format, *args):
        pass

    def __getattr__(self, name):
        # every verb, known or not, goes through the same dispatcher
        if name.startswith("do_"):
            return self._dispatch
        raise AttributeError(name)

    # ---------------------------------------------------------------- output
    def _send(self, status, body, ctype="application/json; charset=utf-8", headers=()):
        self.close_connection = True
        try:
            self.send_response(status)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(body)))
            for k, v in headers:
                self.send_header(k, v)
            self.send_header("Connection", "close")
            self.end_headers()
            if self.command != "HEAD" and body:
                self.wfile.write(body)
            self.wfile.flush()
        except (OSError, ValueError):
            pass

    def _send_error_json(self, status, message, headers=()):
        self._send(status, to_json({"error": message or "error"}).encode("utf-8"), headers=headers)

    def send_error(self, code, message=None, explain=None):
        # used by http.server itself for request lines it cannot read
        if not message:
            message = {400: "bad request", 414: "request line too long", 431: "request headers too large",
                       505: "HTTP version not supported"}.get(code, "request error %d" % code)
        if code == 501:
            code = 400
        if self.request_version == "HTTP/0.9":  # always answer with a status line and headers
            self.request_version = "HTTP/1.0"
        self._send_error_json(code, message)

    # ------------------------------------------------------------------ body
    def _drain(self, n):
        while n > 0:
            chunk = self.rfile.read(min(n, 65536))
            if not chunk:
                break
            n -= len(chunk)

    def _read_body(self):
        raw = self.headers.get("Content-Length")
        if raw is None:
            return b""
        raw = raw.strip()
        if not re.fullmatch(r"[0-9]+", raw):
            raise _Answer(400, "invalid Content-Length %r" % raw)
        n = int(raw)
        if n > MAX_BODY:
            if n <= _DRAIN_LIMIT:
                self._drain(n)
            raise _Answer(413, "request body too large: %d bytes, at most %d" % (n, MAX_BODY))
        data = b""
        while len(data) < n:
            chunk = self.rfile.read(n - len(data))
            if not chunk:
                break
            data += chunk
        return data

    # -------------------------------------------------------------- dispatch
    def _dispatch(self):
        try:
            response = self._handle()
        except _Answer as a:
            self._send_error_json(a.status, a.message, a.headers)
            return
        except TallybookError as e:
            self._send_error_json(_STATUS.get(e.code, 400), e.message or e.code)
            return
        except Exception as e:  # anything unexpected: a 500, nothing printed
            self._send_error_json(500, "internal error: %s" % (str(e) or type(e).__name__))
            return
        self._send(response.status, response.body, response.ctype)

    def _handle(self):
        verb = self.command
        pieces, query = _split_path(self.path)
        found = _route(pieces) if pieces is not None else None
        if found is None:
            self._read_body_quietly()
            raise _Answer(404, "no such path: %s" % self.path.split("?", 1)[0].split("#", 1)[0])
        verbs, name, captured, pieces = found
        if verb not in verbs:
            self._read_body_quietly()
            raise _Answer(405, "method %s not allowed here" % verb, [("Allow", ", ".join(sorted(verbs)))])
        data = self._read_body()
        body = None
        if verb in ("POST", "PUT"):
            ctype = _content_type(self.headers.get("Content-Type"))
            if name == "import":
                if not data:
                    body = ""
                elif ctype in ("text/csv", "text/plain"):
                    body = self._decode(data)
                elif ctype == "application/json":
                    body = self._parse_json(data)
                else:
                    raise _Answer(415, "unsupported content type %s: send application/json, text/csv or "
                                       "text/plain" % (ctype or "(none)"))
            else:
                if data and ctype != "application/json":
                    raise _Answer(415, "unsupported content type %s: send application/json" % (ctype or "(none)"))
                body = self._parse_json(data) if data else {}
        app = self.app
        method = getattr(app, "import_" if name == "import" else name)
        store = Store.open(app.db_path)
        try:
            return method(store, verb, captured, pieces, query, body)
        finally:
            store.close()

    def _read_body_quietly(self):
        try:
            self._read_body()
        except _Answer:
            pass

    @staticmethod
    def _decode(data):
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as e:
            raise ParseError("the body is not valid UTF-8: %s" % e) from None

    def _parse_json(self, data):
        text = self._decode(data)
        try:
            value = json.loads(text)
        except ValueError as e:
            raise ParseError("the body is not valid JSON: %s" % e) from None
        if not isinstance(value, dict):
            raise ValidationError("the body must be a JSON object")
        return value


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def handle_error(self, request, client_address):
        pass


def make_server(db_path, host="127.0.0.1", port=0, today=None):
    """Check the book and bind a server for it (not yet serving). Raises the storage error for a bad book."""
    if today is not None and (not isinstance(today, datetime.date) or isinstance(today, datetime.datetime)):
        raise ValidationError("invalid today %r: expected a date" % (today,))
    if not is_int(port) or not 0 <= port <= 65535:
        raise ValidationError("invalid port %r: expected 0 to 65535" % (port,))
    store = Store.open(db_path)
    try:
        store.info()
    finally:
        store.close()
    handler = type("Handler", (_Handler,), {"app": _App(db_path, today)})
    try:
        return _Server((host, port), handler)
    except OSError as e:
        raise ConflictError("cannot listen on %s:%s: %s" % (host, port, e.strerror or e)) from None


def serve(db_path, host="127.0.0.1", port=0, today=None):
    """Serve the book at db_path until SIGINT or SIGTERM; returns 0 (the exit status)."""
    server = make_server(db_path, host, port, today)
    previous = {}
    stopping = []

    def stop(signum, frame):
        if not stopping:
            stopping.append(signum)
            # shutdown() waits for serve_forever to finish, so it must run in another thread
            threading.Thread(target=server.shutdown, daemon=True).start()

    try:
        if threading.current_thread() is threading.main_thread():
            for sig in (signal.SIGINT, signal.SIGTERM):
                previous[sig] = signal.signal(sig, stop)
        sys.stdout.write("tallybook listening on http://%s:%d\n" % (host, server.server_address[1]))
        sys.stdout.flush()
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
    finally:
        server.server_close()
        for sig, handler in previous.items():
            signal.signal(sig, handler)
    return 0

