class BudgetLine:
    __slots__ = ("_pattern", "_period_kind", "_budget", "_actual", "_remaining", "_percent", "_over", "_accounts")
    _FIELDS = ("pattern", "period_kind", "budget", "actual", "remaining", "percent", "over", "accounts")

    def __init__(self, pattern, period_kind, budget, actual, remaining, percent, over, accounts):
        for name, value in zip(self._FIELDS, (pattern, period_kind, budget, actual, remaining, percent, over,
                                              tuple(tuple(a) for a in accounts))):
            object.__setattr__(self, "_" + name, value)

    pattern = property(lambda self: self._pattern)
