    budget = property(lambda self: self._budget)
    actual = property(lambda self: self._actual)
    remaining = property(lambda self: self._remaining)
    percent = property(lambda self: self._percent)
    over = property(lambda self: self._over)
    accounts = property(lambda self: self._accounts)

    def __setattr__(self, name, value):
        raise AttributeError("BudgetLine is immutable")

    def __delattr__(self, name):
        raise AttributeError("BudgetLine is immutable")

    def _key(self):
        return tuple(getattr(self, "_" + f) for f in self._FIELDS)

    def __reduce__(self):
        return (BudgetLine, self._key())

    def __eq__(self, other):
        if not isinstance(other, BudgetLine):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
